<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class TicketRepository {
 public static function table_name(): string { global $wpdb; return $wpdb->prefix.'avanik_tickets'; }
 public static function install(): void { global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $t=self::table_name(); $c=$wpdb->get_charset_collate(); dbDelta("CREATE TABLE {$t} (id bigint unsigned NOT NULL AUTO_INCREMENT, ticket_id varchar(40) NOT NULL, booking_id varchar(40) NOT NULL, provider varchar(64) NOT NULL DEFAULT '', provider_reference varchar(128) NOT NULL DEFAULT '', pnr varchar(64) NOT NULL DEFAULT '', ticket_number varchar(128) NOT NULL DEFAULT '', voucher_reference varchar(128) NOT NULL DEFAULT '', status varchar(24) NOT NULL DEFAULT 'pending', issued_at datetime DEFAULT NULL, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY ticket_id(ticket_id), KEY booking_id(booking_id), KEY provider_reference(provider_reference), KEY status(status)) {$c};"); }
 public static function create(array $data): string|false { global $wpdb; $id='TKT-'.strtoupper(wp_generate_password(12,false,false)); $ok=$wpdb->insert(self::table_name(),['ticket_id'=>$id,'booking_id'=>sanitize_text_field($data['booking_id']??''),'provider'=>sanitize_text_field($data['provider']??''),'provider_reference'=>sanitize_text_field($data['provider_reference']??''),'pnr'=>sanitize_text_field($data['pnr']??''),'ticket_number'=>sanitize_text_field($data['ticket_number']??''),'voucher_reference'=>sanitize_text_field($data['voucher_reference']??''),'status'=>sanitize_key($data['status']??'issued'),'issued_at'=>$data['issued_at']??current_time('mysql'),'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')],['%s','%s','%s','%s','%s','%s','%s','%s','%s','%s','%s']); return $ok?$id:false; }
 public static function find_by_booking(string $booking_id): array { global $wpdb; return $wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::table_name().' WHERE booking_id=%s ORDER BY id DESC',$booking_id),ARRAY_A)?:[]; }
}